from pathlib import Path
import subprocess

ROOT=Path(__file__).resolve().parent
UPDATER=ROOT/"updater.py"
INDEX=ROOT/"index.html"
BASE_COMMIT="5134009f47dc39b01be0fd4fc33337ea36bc9caa"

def fetch_file(path):
    subprocess.run(["git","fetch","origin",BASE_COMMIT,"--depth=1"],cwd=ROOT,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    r=subprocess.run(["git","show",f"{BASE_COMMIT}:{path}"],cwd=ROOT,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
    return r.stdout

FOCUS_CODE='\nFOCUS_FILE = ROOT / "focus.json"\n\ndef _focus_stock_map(groups):\n    out = {}\n    for g in groups or []:\n        gname = g.get("name") or ""\n        for s in g.get("stocks") or []:\n            t = str(s.get("ticker") or "").upper().strip()\n            if t:\n                z = dict(s)\n                z["group"] = gname\n                out[t] = z\n    return out\n\ndef _focus_dt(ts):\n    try:\n        d = datetime.fromisoformat(str(ts or "").replace("Z", "+00:00"))\n        if d.tzinfo is None:\n            d = d.replace(tzinfo=timezone.utc)\n        return d.astimezone(timezone.utc)\n    except Exception:\n        return None\n\ndef _focus_classify(x, move_abs=0):\n    blob = " ".join([\n        str(x.get("originalTitle") or ""),\n        str(x.get("originalSummary") or ""),\n        str(x.get("title") or ""),\n        str(x.get("summary") or ""),\n    ]).lower()\n\n    # 1 券商升降評／目標價大改\n    if x.get("analystPriority") or any(k in blob for k in [\n        "price target","target price","upgrade","downgrade","overweight",\n        "outperform","underperform","initiated","reiterated","maintained"\n    ]):\n        return 1, "券商調整"\n\n    # 2 財報／財測\n    if any(k in blob for k in [\n        "earnings","quarter results","quarterly results","eps","revenue beat",\n        "revenue miss","earnings beat","earnings miss","raises guidance",\n        "cuts guidance","guidance raised","guidance cut"\n    ]):\n        return 2, "財報／財測"\n\n    # 3 大訂單／新客戶／合作\n    # 政府標案留給順位 5，不在這裡提前歸類\n    gov = any(k in blob for k in [\n        "government","department of defense","dod ","u.s. air force","air force",\n        "navy","army","nasa","federal","contract award","government contract"\n    ])\n    if not gov and any(k in blob for k in [\n        "large order","order win","new customer","customer win","contract",\n        "agreement","partnership","partnered","deal","purchase order",\n        "supply agreement","multi-year"\n    ]):\n        return 3, "訂單／客戶／合作"\n\n    # 4 公司明確展望變化（依使用者要求，排在新產品／政府標案之前）\n    if any(k in blob for k in [\n        "raises outlook","cuts outlook","lowered outlook","lifted outlook",\n        "outlook raised","outlook cut","forecast raised","forecast cut",\n        "expects revenue","expects sales","expects margins","margin outlook",\n        "demand outlook","management expects","company expects",\n        "capacity outlook","backlog outlook","visibility improved"\n    ]):\n        return 4, "公司展望"\n\n    # 5 新產品／政府標案／監管\n    if gov or any(k in blob for k in [\n        "new product","launches","launched","unveils","unveiled","introduces",\n        "introduced","approval","approved","regulatory","fda","faa",\n        "certification","certified","license","licensed","clearance"\n    ]):\n        return 5, "產品／政府／監管"\n\n    # 6 明顯異動＋找到一般公司催化\n    if move_abs >= 3.0 and any(k in blob for k in [\n        "ai","data center","datacenter","demand","pricing","capacity","supply",\n        "customer","order","contract","product","chip","cloud","power","nuclear"\n    ]):\n        return 6, "異動／公司催化"\n\n    # 7 沒有公司催化、較像族群帶動：僅在異動很大時保留\n    if move_abs >= 4.5:\n        return 7, "異動待確認"\n\n    return 99, ""\n\ndef _focus_reason(x):\n    details = x.get("analystDetails") or []\n    reasons = []\n    for d in details:\n        r = str(d.get("reason") or "").strip()\n        if r:\n            reasons.append(r)\n    if reasons:\n        return "；".join(reasons[:2])[:420]\n\n    brief = x.get("investorBrief") or {}\n    for key in ["why", "takeaway", "event"]:\n        v = str(brief.get(key) or "").strip()\n        if v and "來源資訊不足" not in v and "尚未取得足夠內文" not in v:\n            return v[:420]\n\n    return str(x.get("summary") or "").strip()[:420]\n\ndef _focus_judgement(priority, category, x, move_pct):\n    brief = x.get("investorBrief") or {}\n    why = str(brief.get("why") or "").strip()\n    if why and "來源資訊不足" not in why and "尚未取得足夠內文" not in why:\n        return why[:420]\n\n    if priority == 1:\n        return "券商觀點出現明確變化，重點看目標價／評級調整背後的基本面理由，以及後續是否有其他大型券商跟進"\n    if priority == 2:\n        return "核心在財報與財測是否改變未來營收、EPS、毛利率或需求預期，而不是只看單日股價反應"\n    if priority == 3:\n        return "重點看訂單／客戶／合作能否轉成可量化營收，以及金額、出貨時程與延續性"\n    if priority == 4:\n        return "公司展望本身比單一產品消息更重要，優先觀察管理層對需求、營收、毛利、產能或訂單能見度是否上修或下修"\n    if priority == 5:\n        return "先確認新產品、政府標案或監管進展何時能轉成實際出貨與營收，避免只把題材當成短期 EPS 貢獻"\n    if priority == 6:\n        return "股價異動明顯且有公司層級催化，接下來要確認消息能否持續影響訂單、需求或獲利預期"\n    return "股價異動明顯，但目前缺少足夠公司層級催化，較可能包含族群／市場因素，等待更多可驗證資訊"\n\ndef _focus_session_due(existing):\n    now_utc = datetime.now(timezone.utc)\n    now_et = now_utc.astimezone(ZoneInfo("America/New_York"))\n    now_tw = now_utc.astimezone(ZoneInfo("Asia/Taipei"))\n    keys = {str(s.get("key") or "") for s in existing.get("sessions", [])}\n\n    # 美股盤前：以紐約時間判斷 09:00～09:29，DST/EST 自動處理\n    if now_et.weekday() < 5 and now_et.hour == 9 and now_et.minute < 30:\n        key = f"{now_et.date()}:pre"\n        if key not in keys:\n            return "pre", str(now_et.date()), key, now_utc, now_et, now_tw\n\n    # 盤後：台灣時間 08:00～08:29；此時紐約仍是前一個交易日晚上\n    if now_tw.hour == 8 and now_tw.minute < 30 and now_et.weekday() < 5:\n        key = f"{now_et.date()}:post"\n        if key not in keys:\n            return "post", str(now_et.date()), key, now_utc, now_et, now_tw\n\n    # 第一次安裝時若尚無任何資料，早上可先補一份最近盤後焦點，\n    # 避免必須等到隔天 08:00 才看到功能\n    if not existing.get("sessions") and now_tw.hour < 12 and now_et.weekday() < 5:\n        key = f"{now_et.date()}:post"\n        return "post", str(now_et.date()), key, now_utc, now_et, now_tw\n\n    return None\n\ndef refresh_focus_data(groups, news_items):\n    try:\n        existing = json.loads(FOCUS_FILE.read_text(encoding="utf-8")) if FOCUS_FILE.exists() else {"sessions": []}\n    except Exception:\n        existing = {"sessions": []}\n\n    if not isinstance(existing, dict):\n        existing = {"sessions": []}\n    if not isinstance(existing.get("sessions"), list):\n        existing["sessions"] = []\n\n    due = _focus_session_due(existing)\n    if not due:\n        return\n\n    session, market_date, key, now_utc, now_et, now_tw = due\n    stock_map = _focus_stock_map(groups)\n\n    # 盤前看前一晚到開盤前；盤後涵蓋正常交易時段＋盤後資訊\n    lookback_hours = 20 if session == "pre" else 30\n    cutoff = now_utc - timedelta(hours=lookback_hours)\n\n    by_ticker = {}\n    for x in news_items or []:\n        ticker = str(x.get("ticker") or "").upper().strip()\n        if not ticker or ticker == "MARKET" or ticker not in stock_map:\n            continue\n\n        dt = _focus_dt(x.get("ts"))\n        if not dt or dt < cutoff or dt > now_utc + timedelta(minutes=10):\n            continue\n\n        s = stock_map[ticker]\n        if session == "pre":\n            move = s.get("preMarketChangePct")\n        else:\n            move = s.get("changePct")\n        try:\n            move_abs = abs(float(move)) if move is not None else 0.0\n        except Exception:\n            move_abs = 0.0\n\n        priority, category = _focus_classify(x, move_abs)\n        if priority >= 99:\n            continue\n\n        # 低訊號的第 7 類只保留超大異動；前 1～5 類可不受漲幅限制\n        if priority == 7 and move_abs < 4.5:\n            continue\n\n        age_h = max(0.0, (now_utc - dt).total_seconds() / 3600.0)\n        score = (1000 - priority * 100) + min(move_abs, 15) * 6 - age_h * 1.5\n        if x.get("analystPriority"):\n            score += 25\n        if x.get("investorBrief", {}).get("sourceQuality") == "body":\n            score += 10\n\n        by_ticker.setdefault(ticker, []).append((score, priority, category, dt, x))\n\n    items = []\n    for ticker, rows in by_ticker.items():\n        rows.sort(key=lambda z: (z[0], z[3]), reverse=True)\n        best = rows[0]\n        score, priority, category, dt, x = best\n        s = stock_map[ticker]\n\n        if session == "pre":\n            move_pct = s.get("preMarketChangePct")\n            move_price = s.get("preMarketPrice")\n            move_label = "盤前"\n        else:\n            move_pct = s.get("changePct")\n            move_price = s.get("regularPrice")\n            move_label = "收盤"\n\n        highlights = []\n        sources = []\n        for row in rows[:3]:\n            xx = row[4]\n            title = str(xx.get("title") or xx.get("originalTitle") or "").strip()\n            if title and title not in highlights:\n                highlights.append(title)\n            url = str(xx.get("url") or "").strip()\n            if url and not any(z.get("url") == url for z in sources):\n                sources.append({"title": title or "原始來源", "url": url})\n\n        reason = _focus_reason(x)\n        judgement = _focus_judgement(priority, category, x, move_pct)\n\n        items.append({\n            "ticker": ticker,\n            "name": s.get("name") or ticker,\n            "group": s.get("group") or "",\n            "priority": priority,\n            "category": category,\n            "headline": highlights[0] if highlights else "",\n            "highlights": highlights[:3],\n            "reason": reason,\n            "judgement": judgement,\n            "moveLabel": move_label,\n            "movePct": move_pct,\n            "movePrice": move_price,\n            "regularChangePct": s.get("changePct"),\n            "preMarketChangePct": s.get("preMarketChangePct"),\n            "postMarketChangePct": s.get("postMarketChangePct"),\n            "sources": sources[:3],\n            "score": round(float(score), 2),\n        })\n\n    items.sort(key=lambda z: (z.get("priority", 99), -z.get("score", 0)))\n    items = items[:15]\n\n    payload = {\n        "key": key,\n        "session": session,\n        "sessionLabel": "盤前焦點" if session == "pre" else "盤後焦點",\n        "marketDate": market_date,\n        "generatedAt": now_tw.strftime("%Y-%m-%d %H:%M 台灣時間"),\n        "generatedAtIso": now_utc.isoformat(),\n        "items": items,\n    }\n\n    sessions = [s for s in existing.get("sessions", []) if s.get("key") != key]\n    sessions.append(payload)\n    sessions.sort(key=lambda s: str(s.get("generatedAtIso") or ""), reverse=True)\n    sessions = sessions[:20]\n\n    out = {\n        "updatedAt": now_tw.strftime("%Y-%m-%d %H:%M 台灣時間"),\n        "schedule": {\n            "pre": "美東 09:00（開盤前 30 分鐘，自動依 DST/EST）",\n            "post": "台灣 08:00",\n        },\n        "priority": [\n            "1 券商升降評／目標價大改",\n            "2 財報／財測",\n            "3 大訂單／新客戶／合作",\n            "4 公司明確展望變化",\n            "5 新產品／政府標案／監管",\n            "6 明顯異動＋公司催化",\n            "7 超大異動但催化待確認",\n        ],\n        "sessions": sessions,\n    }\n    FOCUS_FILE.write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")\n'
CSS='\n/* 美股焦點股 */\n.newsSubSwitch{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0 16px}\n.newsSubSwitch button,.focusSessionSwitch button{border:1px solid #263d5a;background:#11233d;color:#9fb0c7;border-radius:16px;padding:12px 10px;font-weight:800;font-size:15px}\n.newsSubSwitch button.on,.focusSessionSwitch button.on{border-color:#52d8ff;color:#dff8ff;box-shadow:0 0 0 1px #52d8ff inset}\n.focusPanel{display:none}\n.focusPanel.on{display:block}\n.focusToolbar{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:8px 0 14px}\n.focusSessionSwitch{display:flex;gap:8px}\n.focusDate{background:#0e1d31;color:#dbe9f7;border:1px solid #263d5a;border-radius:12px;padding:9px 10px;font-weight:700}\n.focusInfo{color:#8ea3bd;font-size:13px;line-height:1.5;margin:8px 0 14px}\n.focusGrid{display:grid;grid-template-columns:1fr;gap:14px}\n.focusCard{background:#0e1d31;border:1px solid #263d5a;border-radius:18px;overflow:hidden}\n.focusHead{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding:16px 16px 12px;background:#122641;border-bottom:1px solid #263d5a}\n.focusTicker{font-size:20px;font-weight:900;color:#f4f8ff}\n.focusGroup{font-size:13px;color:#8ea3bd;margin-top:3px}\n.focusMove{text-align:right;font-size:21px;font-weight:900;white-space:nowrap}\n.focusBody{padding:15px 16px 17px}\n.focusPill{display:inline-block;border:1px solid #2c6d86;border-radius:999px;color:#62ddff;padding:5px 9px;font-size:12px;font-weight:800;margin-bottom:10px}\n.focusHeadline{font-size:17px;line-height:1.5;font-weight:850;color:#f5f8fc;margin-bottom:10px}\n.focusHighlights{margin:0 0 12px;padding-left:20px;color:#d8e3ee;line-height:1.55}\n.focusReason,.focusJudge{border:1px solid #263d5a;border-radius:13px;padding:11px 12px;margin-top:10px;color:#c9d6e3;line-height:1.55;font-size:14px}\n.focusLabel{display:block;color:#59d8ff;font-weight:900;margin-bottom:5px}\n.focusSources{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}\n.focusSources a{color:#54d8ff;text-decoration:none;font-weight:800;font-size:13px}\n@media(min-width:760px){.focusGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}\n'
NEWS_SECTION_OLD='<section id="news" class="page"><div class="title">市場新聞</div>\n<div class="sub">預設顯示最新且重要的新聞；輸入股票 Ticker 可搜尋最近 30 天新聞，不分大小寫</div>\n<div class="topnewsbar"><button id="top10Toggle" class="top10btn">今日十大重要新聞</button><span id="top10Note" class="top10note">盤前＋盤中＋盤後</span></div>\n<div class="searchbar"><input id="newsSearch" type="search" placeholder="輸入 Ticker，例如 MU、NVDA、VICR"><button id="clearSearch" class="clearbtn">清除</button></div>\n<div id="resultInfo" class="resultinfo">顯示最新重要新聞</div>\n<div id="newsgrid" class="newsgrid"></div></section>'
NEWS_SECTION_NEW='<section id="news" class="page"><div class="title">新聞</div>\n<div class="newsSubSwitch"><button class="on" data-nmode="market">市場新聞</button><button data-nmode="focus">美股焦點股</button></div>\n<div id="newsMarketPanel">\n<div class="sub">預設顯示最新且重要的新聞；輸入股票 Ticker 可搜尋最近 30 天新聞，不分大小寫</div>\n<div class="topnewsbar"><button id="top10Toggle" class="top10btn">今日十大重要新聞</button><span id="top10Note" class="top10note">盤前＋盤中＋盤後</span></div>\n<div class="searchbar"><input id="newsSearch" type="search" placeholder="輸入 Ticker，例如 MU、NVDA、VICR"><button id="clearSearch" class="clearbtn">清除</button></div>\n<div id="resultInfo" class="resultinfo">顯示最新重要新聞</div>\n<div id="newsgrid" class="newsgrid"></div>\n</div>\n<div id="focusPanel" class="focusPanel">\n<div class="sub">只保留真正值得看的公司催化｜盤前：美東 09:00｜盤後：台灣 08:00</div>\n<div class="focusToolbar">\n  <div class="focusSessionSwitch"><button class="on" data-fmode="pre">盤前焦點</button><button data-fmode="post">盤後焦點</button></div>\n  <select id="focusDate" class="focusDate"></select>\n</div>\n<div id="focusInfo" class="focusInfo">載入焦點股中…</div>\n<div id="focusGrid" class="focusGrid"></div>\n</div>\n</section>'
FOCUS_JS='\nlet __focusData=null,__focusMode="pre";\n\nasync function loadFocus(force=false){\n  if(__focusData && !force){renderFocus();return}\n  const info=document.getElementById("focusInfo");\n  if(info)info.textContent="載入焦點股中…";\n  try{\n    const r=await fetch("focus.json?"+Date.now(),{cache:"no-store"});\n    if(!r.ok)throw new Error("no focus.json");\n    __focusData=await r.json();\n    const sessions=Array.isArray(__focusData.sessions)?__focusData.sessions:[];\n    if(sessions.length && !sessions.some(s=>s.session===__focusMode)){\n      __focusMode=sessions[0].session||"post";\n    }\n    renderFocus();\n  }catch(e){\n    if(info)info.textContent="尚無焦點股資料｜第一次會在盤前或盤後更新時自動建立";\n    const g=document.getElementById("focusGrid");if(g)g.innerHTML="";\n  }\n}\n\nfunction focusFmt(v){\n  if(v==null||Number.isNaN(Number(v)))return"--";\n  const n=Number(v);return (n>0?"+":"")+n.toFixed(2)+"%";\n}\n\nfunction renderFocus(){\n  const data=__focusData||{},all=Array.isArray(data.sessions)?data.sessions:[];\n  const modeSessions=all.filter(s=>s.session===__focusMode);\n  document.querySelectorAll("[data-fmode]").forEach(b=>b.classList.toggle("on",b.dataset.fmode===__focusMode));\n\n  const sel=document.getElementById("focusDate");\n  const info=document.getElementById("focusInfo");\n  const grid=document.getElementById("focusGrid");\n  if(!sel||!grid)return;\n\n  const old=sel.value;\n  sel.innerHTML=modeSessions.map((s,i)=>`<option value="${escapeHtml(s.key||"")}">${escapeHtml(s.marketDate||"")}｜${escapeHtml(s.sessionLabel||"")}</option>`).join("");\n  if(old && modeSessions.some(s=>s.key===old))sel.value=old;\n\n  const chosen=modeSessions.find(s=>s.key===sel.value)||modeSessions[0];\n  if(!chosen){\n    if(info)info.textContent=`目前沒有${__focusMode==="pre"?"盤前":"盤後"}焦點資料`;\n    grid.innerHTML="";\n    return;\n  }\n  sel.value=chosen.key||"";\n\n  const rows=Array.isArray(chosen.items)?chosen.items:[];\n  if(info)info.textContent=`${chosen.marketDate||""}｜${chosen.sessionLabel||""}｜更新 ${chosen.generatedAt||"--"}｜共 ${rows.length} 檔`;\n\n  grid.innerHTML=rows.map(x=>{\n    const mv=Number(x.movePct);\n    const moveClass=mv>0?"pos":mv<0?"neg":"";\n    const ah=x.postMarketChangePct!=null?`<div class="focusGroup">盤後 ${focusFmt(x.postMarketChangePct)}</div>`:"";\n    const hs=(Array.isArray(x.highlights)?x.highlights:[]).slice(1,3);\n    const extras=hs.length?`<ul class="focusHighlights">${hs.map(h=>`<li>${escapeHtml(h)}</li>`).join("")}</ul>`:"";\n    const src=(Array.isArray(x.sources)?x.sources:[]).slice(0,3);\n    return `<article class="focusCard">\n      <div class="focusHead">\n        <div><div class="focusTicker">${escapeHtml(x.ticker||"")} <span class="focusGroup">｜${escapeHtml(x.name||"")}</span></div><div class="focusGroup">${escapeHtml(x.group||"")}</div></div>\n        <div class="focusMove ${moveClass}">${escapeHtml(x.moveLabel||"")} ${focusFmt(x.movePct)}${ah}</div>\n      </div>\n      <div class="focusBody">\n        <div class="focusPill">順位 ${x.priority||"--"}｜${escapeHtml(x.category||"")}</div>\n        <div class="focusHeadline">${escapeHtml(x.headline||"")}</div>\n        ${extras}\n        ${x.reason?`<div class="focusReason"><span class="focusLabel">新增重點</span>${escapeHtml(x.reason)}</div>`:""}\n        <div class="focusJudge"><span class="focusLabel">判讀</span>${escapeHtml(x.judgement||"")}</div>\n        ${src.length?`<div class="focusSources">${src.map(s=>`<a target="_blank" rel="noopener" href="${escapeHtml(s.url||"#")}">查看來源 ↗</a>`).join("")}</div>`:""}\n      </div>\n    </article>`;\n  }).join("");\n}\n\ndocument.querySelectorAll("[data-nmode]").forEach(b=>b.addEventListener("click",()=>{\n  const mode=b.dataset.nmode;\n  document.querySelectorAll("[data-nmode]").forEach(x=>x.classList.toggle("on",x===b));\n  const market=document.getElementById("newsMarketPanel");\n  const focus=document.getElementById("focusPanel");\n  if(mode==="focus"){\n    if(market)market.style.display="none";\n    if(focus)focus.classList.add("on");\n    loadFocus(true);\n  }else{\n    if(market)market.style.display="";\n    if(focus)focus.classList.remove("on");\n    renderNews();\n  }\n}));\n\ndocument.querySelectorAll("[data-fmode]").forEach(b=>b.addEventListener("click",()=>{\n  __focusMode=b.dataset.fmode;\n  renderFocus();\n}));\ndocument.getElementById("focusDate")?.addEventListener("change",renderFocus);\n\nwindow.addEventListener("pageshow",()=>{\n  if(document.getElementById("focusPanel")?.classList.contains("on"))loadFocus(true);\n});\ndocument.addEventListener("visibilitychange",()=>{\n  if(document.visibilityState==="visible" && document.getElementById("focusPanel")?.classList.contains("on"))loadFocus(true);\n});\n'

def patch_updater(src):
    if len(src)<230000: raise RuntimeError(f'base updater unexpectedly small: {len(src)}')

    # Keep Yahoo/yfinance malformed news rows from crashing the whole run.
    old='''    for obj in raw[:12]:\n        c = obj.get("content", obj) if isinstance(obj, dict) else {}\n        title = (c.get("title") or obj.get("title") or "").strip()'''
    new='''    for obj in raw[:12]:\n        if not isinstance(obj, dict):\n            continue\n        c = obj.get("content") or obj\n        if not isinstance(c, dict):\n            c = {}\n        title = (c.get("title") or obj.get("title") or "").strip()'''
    if old in src: src=src.replace(old,new,1)

    marker='if os.getenv("SKIP_EARNINGS", "0") != "1":'
    if marker not in src: raise RuntimeError('focus insertion marker missing')
    if 'def refresh_focus_data(groups, news_items):' not in src:
        src=src.replace(marker,FOCUS_CODE+'\n'+marker,1)

    call_marker='news = _clean_cached_news(news)\nhistory_db = _clean_cached_news(history_db)'
    if call_marker not in src: raise RuntimeError('focus call marker missing')
    if 'refresh_focus_data(groups, news)' not in src:
        src=src.replace(call_marker,call_marker+'\nrefresh_focus_data(groups, news)',1)
    return src

def patch_index(src):
    if '美股焦點股' not in src:
        if NEWS_SECTION_OLD not in src: raise RuntimeError('news section marker missing')
        src=src.replace(NEWS_SECTION_OLD,NEWS_SECTION_NEW,1)
        if '</style>' not in src: raise RuntimeError('style marker missing')
        src=src.replace('</style>',CSS+'\n</style>',1)
        js_marker='function renderNews(){'
        if js_marker not in src: raise RuntimeError('renderNews marker missing')
        src=src.replace(js_marker,FOCUS_JS+'\n'+js_marker,1)
    return src

def main():
    updater=patch_updater(fetch_file('updater.py'))
    index=patch_index(fetch_file('index.html'))
    compile(updater,'updater.py','exec')
    for token in ['refresh_focus_data(groups, news)','4 公司明確展望變化','5 新產品／政府標案／監管']:
        if token not in updater: raise RuntimeError(f'focus updater self-test missing: {token}')
    for token in ['美股焦點股','data-nmode="focus"','loadFocus(true)']:
        if token not in index: raise RuntimeError(f'focus frontend self-test missing: {token}')
    UPDATER.write_text(updater,encoding='utf-8')
    INDEX.write_text(index,encoding='utf-8')
    print(f'Focus feature installed; updater {len(updater)} bytes')
    code=compile(updater,str(UPDATER),'exec')
    g={'__name__':'__main__','__file__':str(UPDATER),'__package__':None}
    exec(code,g,g)

if __name__=='__main__':
    main()
